#!/usr/bin/env bash
# Reproducible Gradle-free build of the Sparc Quest APK (arm64-v8a, NativeActivity + OpenXR).
# Usage: ./build.sh [debug|release] [open|clean|original|mix]   (run from Git Bash on Windows, or any POSIX shell)
#   open     (default) Project Arena art + sound (tools/build_open_assets.py) -> shareable, no CCP assets
#   clean    earlier procedural set generated by tools/gen_clean_*.py -> shareable, no CCP assets
#   original           assets extracted from the user's own Sparc install (personal use only)
# Requires: Android SDK (build-tools 34.0.0, platforms;android-32), NDK r26 (26.3.11579264), JDK 17+.
set -euo pipefail

MODE="${1:-debug}"
ASSET_SET="${2:-open}"
ROOT="$(cd "$(dirname "$0")" && pwd)"
SDK="${ANDROID_HOME:-/c/Android/sdk}"
NDK="${ANDROID_NDK_HOME:-$SDK/ndk/26.3.11579264}"
BT="$SDK/build-tools/34.0.0"
PLATFORM="$SDK/platforms/android-32/android.jar"
JAVA_HOME="${JAVA_HOME:-/c/Program Files/Eclipse Adoptium/jdk-21.0.12.101-hotspot}"
OXR="$ROOT/third_party/openxr_aar"
OUT="$ROOT/build/$MODE-$ASSET_SET"
case "$ASSET_SET" in
  original) ASSET_DIR="$ROOT/app/assets" ;;
  open) ASSET_DIR="$ROOT/app/assets_open" ;;
  mix) ASSET_DIR="$ROOT/build/assets_mix" ;;   # local test: original assets with open court/stadium (never shared)
  *) ASSET_DIR="$ROOT/app/assets_clean" ;;
esac
# releases may only ship our own art (no CCP-derived assets)
if [ "$MODE" = release ] && [ "$ASSET_SET" != open ]; then
  echo "release builds must use the open asset set (got '$ASSET_SET')" >&2; exit 1
fi
API=29

case "$(uname -s)" in
  MINGW*|MSYS*|CYGWIN*) HOST=windows-x86_64; EXE=.exe ;;
  Darwin) HOST=darwin-x86_64; EXE= ;;
  *) HOST=linux-x86_64; EXE= ;;
esac
CXX="$NDK/toolchains/llvm/prebuilt/$HOST/bin/clang++$EXE"
CC="$NDK/toolchains/llvm/prebuilt/$HOST/bin/clang$EXE"
SYSROOT="$NDK/toolchains/llvm/prebuilt/$HOST/sysroot"
TARGET="aarch64-linux-android$API"

mkdir -p "$OUT/obj" "$OUT/apk/lib/arm64-v8a"

if [ "$MODE" = release ]; then OPT="-O2 -DNDEBUG"; else OPT="-O2 -g"; fi
CFLAGS="--target=$TARGET --sysroot=$SYSROOT -fPIC -ffunction-sections -fdata-sections $OPT -Wall -Wno-unused-function"
INC="-I$ROOT/app/src -I$NDK/sources/android/native_app_glue -I$OXR/prefab/modules/headers/include"

python -I "$ROOT/tools/write_servers_header.py"
echo "== compiling"
objs=()
"$CC" $CFLAGS $INC -c "$NDK/sources/android/native_app_glue/android_native_app_glue.c" -o "$OUT/obj/glue.o"
objs+=("$OUT/obj/glue.o")
for f in "$ROOT"/app/src/*.cpp; do
  o="$OUT/obj/$(basename "${f%.cpp}").o"
  "$CXX" $CFLAGS -std=c++17 -fno-exceptions -fno-rtti $INC -c "$f" -o "$o"
  objs+=("$o")
done

echo "== linking"
"$CXX" --target=$TARGET --sysroot=$SYSROOT -shared -o "$OUT/apk/lib/arm64-v8a/libprojectarena.so" "${objs[@]}" \
  -L"$OXR/jni/arm64-v8a" -lopenxr_loader -landroid -llog -lEGL -lGLESv3 -laaudio -lm \
  -static-libstdc++ -Wl,--gc-sections -Wl,-u,ANativeActivity_onCreate -Wl,--no-undefined -Wl,-z,max-page-size=16384
cp "$OXR/jni/arm64-v8a/libopenxr_loader.so" "$OUT/apk/lib/arm64-v8a/"
if [ "$MODE" = release ]; then
  "$NDK/toolchains/llvm/prebuilt/$HOST/bin/llvm-strip$EXE" --strip-unneeded "$OUT/apk/lib/arm64-v8a/libprojectarena.so"
fi

echo "== packaging"
"$BT/aapt2$EXE" link -o "$OUT/base.apk" --manifest "$ROOT/app/AndroidManifest.xml" -I "$PLATFORM" \
  -A "$ASSET_DIR" --min-sdk-version 32 --target-sdk-version 34 --no-compile-sdk-metadata -0 tex -0 mdl -0 col -0 wav
# add native libs uncompressed (extractNativeLibs=false) then page-align
python -I "$ROOT/tools/add_libs.py" "$OUT/base.apk" "$OUT/apk" "$OUT/unaligned.apk"
"$BT/zipalign$EXE" -f -p 4 "$OUT/unaligned.apk" "$OUT/aligned.apk"
if [ "$ASSET_SET" = open ]; then python -I "$ROOT/tools/check_open_apk.py" "$OUT/aligned.apk" "$ASSET_DIR"; fi

echo "== signing"
KS="$ROOT/build/debug.keystore"
if [ ! -f "$KS" ]; then
  "$JAVA_HOME/bin/keytool$EXE" -genkeypair -keystore "$KS" -storepass android -keypass android -alias androiddebugkey \
    -keyalg RSA -keysize 2048 -validity 10000 -dname "CN=Android Debug,O=Android,C=US" >/dev/null
fi
APK="$ROOT/build/ProjectArena-$MODE-$ASSET_SET.apk"
# release builds are signed with the same local key unless PROJECTARENA_KEYSTORE/PROJECTARENA_KEY_ALIAS/PROJECTARENA_KEY_PASS are set
if [ "$MODE" = release ] && { [ -z "$PROJECTARENA_KEYSTORE" ] || [ -z "$PROJECTARENA_KEY_PASS" ]; }; then
  echo "release builds need your release key: set PROJECTARENA_KEYSTORE, PROJECTARENA_KEY_ALIAS and PROJECTARENA_KEY_PASS" >&2; exit 1
fi
KSUSE="${PROJECTARENA_KEYSTORE:-$KS}"; ALIAS="${PROJECTARENA_KEY_ALIAS:-androiddebugkey}"; PASS="${PROJECTARENA_KEY_PASS:-android}"
JAVA_HOME="$JAVA_HOME" PATH="$JAVA_HOME/bin:$PATH" "$BT/apksigner.bat" sign --ks "$KSUSE" --ks-pass "pass:$PASS" \
  --ks-key-alias "$ALIAS" --out "$APK" "$OUT/aligned.apk" 2>/dev/null || \
JAVA_HOME="$JAVA_HOME" PATH="$JAVA_HOME/bin:$PATH" "$BT/apksigner" sign --ks "$KSUSE" --ks-pass "pass:$PASS" \
  --ks-key-alias "$ALIAS" --out "$APK" "$OUT/aligned.apk"
JAVA_HOME="$JAVA_HOME" PATH="$JAVA_HOME/bin:$PATH" "$BT/apksigner.bat" verify "$APK" 2>/dev/null || \
JAVA_HOME="$JAVA_HOME" PATH="$JAVA_HOME/bin:$PATH" "$BT/apksigner" verify "$APK"
ls -la "$APK"
echo "built $APK"
